请对以下 case 进行三维加权评分。

=== case_id ===
Case-29-elderly-care-009

=== 用户原始指令 (query.txt) ===
给我整一个哈,字叠在图上的,一行带数字,危险了给我提醒

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "给我整一个哈,字叠在图上的,一行带数字,危险了给我提醒",
  "size": "2x2",
  "eventCandidates": [],
  "dataModelSchema": {
    "card": {
      "title": {
        "type": "string",
        "description": "老人看护卡片标题",
        "sampleValue": "看护"
      }
    },
    "asset": {
      "alertIcon": {
        "type": "string",
        "description": "高温危险提醒图标资源路径",
        "sampleValue": "resources/base/media/icon_high_temperature.png"
      }
    },
    "primary": {
      "value": {
        "type": "string",
        "description": "当前危险指标主数值",
        "sampleValue": "38.2"
      },
      "caption": {
        "type": "string",
        "description": "主数值对应的看护状态说明",
        "sampleValue": "体温危险"
      }
    },
    "support": {
      "label": {
        "type": "string",
        "description": "危险状态提醒标签",
        "sampleValue": "危险"
      },
      "value": {
        "type": "string",
        "description": "带数字的一行提醒摘要",
        "sampleValue": "体温38.2℃"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_high_temperature.png",
      "description": "亲人关怀场景的高温/温度计图标，适合表达老人看护中的体温异常和危险提醒。",
      "bindTo": "/asset/alertIcon"
    }
  ]
}

